<section class="ios-card p-5"><div class="flex items-start justify-between gap-3"><div><h2 class="text-sm font-semibold">Soportes reservados</h2><p class="mt-1 text-[11px] leading-5 text-slate-400">PDF, JPG o PNG · máximo 10 MB. Nunca se publican en el centro general de evidencias.</p></div><?= icon('lock','h-5 w-5 text-slate-400') ?></div><div class="mt-4 space-y-3"><?php foreach($supports as $support): ?><article class="rounded-xl bg-slate-50 p-3"><div class="flex items-start justify-between gap-2"><div><p class="text-xs font-semibold text-slate-700"><?= e($support['titulo']) ?></p><p class="mt-1 text-[10px] text-slate-400"><?= e($support['categoria']) ?> · <?= e($support['nombre_original']) ?></p><p class="mt-1 text-[10px] <?= $support['estado_revision']==='Revisado'?'text-emerald-600':'text-amber-600' ?>"><?= e($support['estado_revision']) ?><?= $support['revisado_at']?' · '.format_date($support['revisado_at'],true):'' ?></p></div><a href="<?= e(url('/soportes-reservados/'.$support['id'].'/descargar')) ?>" class="btn-icon" title="Descargar de forma privada"><?= icon('download','h-4 w-4') ?></a></div><?php if($support['estado_revision']!=='Revisado'): ?><form method="post" action="<?= e(url('/soportes-reservados/'.$support['id'].'/revision')) ?>" class="mt-2"><?= csrf_field() ?><input type="hidden" name="return_url" value="<?= e($returnUrl) ?>"><button class="text-link text-[10px]" type="submit">Marcar revisión humana</button></form><?php endif; ?></article><?php endforeach; ?><?php if(!$supports): ?><p class="rounded-xl bg-slate-50 p-3 text-xs text-slate-400">Sin soportes reservados.</p><?php endif; ?></div><details class="mt-4 rounded-xl border border-slate-200 p-3"><summary class="cursor-pointer text-xs font-semibold text-blue-600">Cargar soporte</summary><form method="post" enctype="multipart/form-data" action="<?= e(url('/soportes-reservados')) ?>" class="mt-3 space-y-3"><?= csrf_field() ?><input type="hidden" name="area" value="<?= e($area) ?>"><input type="hidden" name="entidad_tipo" value="<?= e($entityType) ?>"><input type="hidden" name="entidad_id" value="<?= (int)$entityId ?>"><input type="hidden" name="return_url" value="<?= e($returnUrl) ?>"><div><label class="label">Título *</label><input name="titulo" class="input" required maxlength="240"></div><div><label class="label">Categoría *</label><input name="categoria" class="input" required maxlength="100" placeholder="Concepto, acta, informe agregado…"></div><div><label class="label">Archivo *</label><input type="file" name="archivo" class="input" accept=".pdf,.jpg,.jpeg,.png" required></div><button class="btn-secondary w-full" type="submit"><?= icon('upload','h-4 w-4') ?> Guardar en expediente reservado</button></form></details></section>
